const GUN_SAMPLE_DATA={"rifle0":"data:audio/mpeg;base64,","rifle1":"data:audio/mpeg;base64,","rifle2":"data:audio/mpeg;base64,","rifle3":"data:audio/mpeg;base64,","rifle4":"data:audio/mpeg;base64,","auto0":"data:audio/mpeg;base64,","auto1":"data:audio/mpeg;base64,","auto2":"data:audio/mpeg;base64,","auto3":"data:audio/mpeg;base64,","cannon0":"data:audio/mpeg;base64,","cannon1":"data:audio/mpeg;base64,","cannon2":"data:audio/mpeg;base64,","cannon3":"data:audio/mpeg;base64,","cannon4":"data:audio/mpeg;base64,","scatter":"data:audio/mpeg;base64,","metal0":"data:audio/mpeg;base64,","blast0":"data:audio/mpeg;base64,","thrust0":"data:audio/mpeg;base64,","metal1":"data:audio/mpeg;base64,","blast1":"data:audio/mpeg;base64,","thrust1":"data:audio/mpeg;base64,","metal2":"data:audio/mpeg;base64,","blast2":"data:audio/mpeg;base64,","thrust2":"data:audio/mpeg;base64,","pressure0":"data:audio/mpeg;base64,","charge0":"data:audio/mpeg;base64,","rail0":"data:audio/mpeg;base64,","action0":"data:audio/mpeg;base64,","pressure1":"data:audio/mpeg;base64,","charge1":"data:audio/mpeg;base64,","rail1":"data:audio/mpeg;base64,","action1":"data:audio/mpeg;base64,"};
const GUN_POOLS={
 rifle:['rifle0','rifle1','rifle2','rifle3','rifle4'],
 auto:['auto0','auto1','auto2','auto3'],
 cannon:['cannon0','cannon1','cannon2','cannon3','cannon4'],
 metal:['metal0','metal1','metal2'],
 blast:['blast0','blast1','blast2'],
 thrust:['thrust0','thrust1','thrust2'],
 pressure:['pressure0','pressure1'],
 charge:['charge0','charge1'],
 rail:['rail0','rail1'],
 action:['action0','action1']
};
const GUN_VOICES={
 rifle:{echo:'short',echoLevel:.24,pool:'rifle',gain:.76,rate:1.05,drop:.09,action:.13},
 hailstorm:{echo:'short',echoLevel:.17,pool:'auto',gain:.66,rate:.93,drop:.05,action:.12},
 kite:{echo:'short',echoLevel:.30,pool:'auto',gain:.86,rate:.73,drop:.11,pressure:.18},
 shotgun:{echo:'metal',echoLevel:.38,pool:'scatter',gain:.89,rate:.94,pressure:.24,action:.24},
 rampart:{echo:'heavy',echoLevel:.33,pool:'cannon',gain:.95,rate:.93,pressure:.49,action:.22},
 javelin:{echo:'heavy',echoLevel:.42,pool:'cannon',gain:1.00,rate:.75,pressure:.67,blast:.30,action:.22},
 morrow:{echo:'heavy',echoLevel:.27,pool:'cannon',gain:.86,rate:1.09,pressure:.39,action:.22},
 rail:{echo:'metal',echoLevel:.35,pool:'rail',gain:.67,rate:1.00,pressure:.42,crack:.46},
 missile:{echo:'blast',echoLevel:.29,pool:'blast',gain:.82,rate:1.24,thrust:.77,pressure:.31},
 locust:{echo:'blast',echoLevel:.35,pool:'blast',gain:.78,rate:.92,thrust:.68,pressure:.44}
};
// Extra weapons keep their current gameplay timing and share only their acoustic family.
for(const [name,family,rate,gain] of [
 ['quill-lance','rifle',1.04,.78],['sidewinder','rifle',1.16,.67],['trident','rifle',.94,.82],['needle-carbine','rifle',1.10,.67],['salt-mg','hailstorm',.88,.86],
 ['watchman','rifle',.88,.88],['rivet','hailstorm',.87,.75],['forge','rampart',1.16,.84],
 ['falcon','rampart',1.10,.86],['giza-salvo','morrow',.95,1.04],['vyzov-cross','rampart',.78,.84],['flechette-scattergun','shotgun',1.14,.78],
 ['ember','rail',1.20,.67],['parallax','rail',.86,.73],['obelisk','rail',.74,.84],
 ['cerberus','missile',1.12,.77],['vesper-shoulder','missile',1.03,.81]
]){
 GUN_VOICES[name]={...GUN_VOICES[family],rate,gain};
}
// Keep audio variation independent of combat rules, replays and simulation seeds.
let gunAudioSeed=Date.now()>>>0;
function gunAudioRandom(){
 gunAudioSeed=(Math.imul(gunAudioSeed,1664525)+1013904223)>>>0;
 return gunAudioSeed/4294967296;
}
const gunSampleBuffers=new Map(),gunChoices=new Map();
let gunBankLoad=null;
async function loadGunBank(){
 await Promise.all(Object.entries(GUN_SAMPLE_DATA).map(async ([name,url])=>{
  const bytes=Uint8Array.from(atob(url.split(',')[1]),char=>char.charCodeAt(0));
  try{gunSampleBuffers.set(name,await audio.decodeAudioData(bytes.buffer))}
  catch(error){console.warn('Unable to decode Iron Vow audio sample '+name,error)}
 }));

}
function nextGunSample(pool){
 const variants=GUN_POOLS[pool];
 if(!variants)return pool;
 if(!gunChoices.has(pool))gunChoices.set(pool,{remaining:[],last:null});
 const choice=gunChoices.get(pool);
 if(!choice.remaining.length)choice.remaining=variants.slice();
 const eligible=choice.remaining.filter(name=>name!==choice.last);
 const available=eligible.length?eligible:choice.remaining;
 const name=available[Math.floor(gunAudioRandom()*available.length)];
 choice.remaining.splice(choice.remaining.indexOf(name),1);
 choice.last=name;
 return name;
}
// Three filtered reflections per profile. The dry cue still follows the muzzle or target.
const GUN_ECHOES={
 short:{highpass:210,taps:[[.053,3100,.76,-.36],[.116,2300,.36,.42],[.197,1600,.14,0]]},
 metal:{highpass:150,taps:[[.071,3500,.72,.46],[.152,2350,.43,-.46],[.258,1550,.19,.12]]},
 heavy:{highpass:105,taps:[[.094,2700,.76,-.44],[.201,1750,.51,.47],[.351,1150,.23,-.12]]},
 blast:{highpass:95,taps:[[.113,3000,.77,.48],[.247,1700,.49,-.50],[.447,1050,.23,.08]]}
};
const gunEchoInputs=new Map();
function gunEchoInput(kind){
 if(gunEchoInputs.has(kind))return gunEchoInputs.get(kind);
 const profile=GUN_ECHOES[kind];
 const input=audio.createBiquadFilter();
 input.type='highpass';input.frequency.value=profile.highpass;
 for(const [seconds,cutoff,level,pan] of profile.taps){
  const delay=audio.createDelay(.5),filter=audio.createBiquadFilter(),gain=audio.createGain();
  delay.delayTime.value=seconds;
  filter.type='lowpass';filter.frequency.value=cutoff;
  gain.gain.value=level;
  input.connect(delay);delay.connect(filter);filter.connect(gain);
  if(audio.createStereoPanner){
   const position=audio.createStereoPanner();
   position.pan.value=pan;gain.connect(position);position.connect(soundBus);
  }else gain.connect(soundBus);
 }
 gunEchoInputs.set(kind,input);
 return input;
}
function playGunMix(type,now,volume,detail){
 const {pan=0,rate:beatRate=1,travel=.46,lastReport,weaponVoice}=detail;
 const sample=(pool,at,level,rate=1,position=pan,maxDuration=0,echo=null,echoLevel=0)=>{
  const name=nextGunSample(pool),buffer=gunSampleBuffers.get(name);
  if(!buffer)return;
  const source=audio.createBufferSource(),gain=audio.createGain();
  source.buffer=buffer;
  source.playbackRate.value=rate*(.95+gunAudioRandom()*.10);
  const amplitude=level*volume*(.91+gunAudioRandom()*.18);
  gain.gain.setValueAtTime(amplitude,at);
  if(maxDuration){
   gain.gain.setValueAtTime(amplitude,at+maxDuration*.58);
   gain.gain.linearRampToValueAtTime(0,at+maxDuration);
  }
  source.connect(gain);
  if(position&&audio.createStereoPanner){
   const panner=audio.createStereoPanner();
   panner.pan.value=position;gain.connect(panner);panner.connect(soundBus);
  }else gain.connect(soundBus);
  if(echo){
   const send=audio.createGain();
   send.gain.value=echoLevel;
   gain.connect(send);send.connect(gunEchoInput(echo));
  }
  source.start(at);
  if(maxDuration)source.stop(at+maxDuration);
 };
 const voice=type==='gunReport'?GUN_VOICES[weaponVoice]:null;
 if(voice){
  const rate=voice.rate*beatRate;
  sample(voice.pool,now,voice.gain,rate,pan,0,voice.echo,voice.echoLevel);
  if(voice.crack)sample('cannon',now,voice.crack,1.32,pan,.14,voice.echo,voice.echoLevel*.45);
  if(voice.pressure)sample('pressure',now+.009,voice.pressure,rate,pan,voice.thrust?.34:.52);
  if(voice.blast)sample('blast',now+.015,voice.blast,.68,pan,.52);
  if(voice.thrust)sample('thrust',now+.025,voice.thrust,rate,pan,Math.min(travel,.52));
  if(voice.action&&lastReport)sample('action',now+(weaponVoice==='shotgun'?.26:.065),voice.action, .91,pan);
  return true;
 }
 if(type==='parallax-charge'){
  sample('charge',now,.26,.60,pan,.46);
  return true;
 }
 if(type==='gunReport')return true;
 if(type==='missileArm'){
  sample('action',now,.30,.85,pan,.16);
  sample('charge',now+.018,.20,.77,pan,.18);
  return true;
 }
 if(type==='armorImpact'||type==='heavyImpact'||type==='shieldImpact'){
  const heavy=type==='heavyImpact',shield=type==='shieldImpact',shell=detail.material==='tank',airframe=detail.material==='helicopter';
  const gun=GUN_VOICES[detail.weaponVoice];
  const echo=gun&&(gun.echo==='heavy'?'heavy':heavy||shell?'metal':'short');
  sample('metal',now,shield?.73:heavy?.78:.57,shield?1.45:shell?.77:airframe?1.26:1,pan,heavy?.34:.21,shield?'metal':echo,shield?.29:gun?gun.echoLevel*.95:0);
  if(shield)sample('action',now+.026,.25,1.35,pan,.14);
  if(heavy||shell)sample('pressure',now+.014,heavy?.26:.13,shell?.83:1.15,pan,.34);
  return true;
 }
 if(type==='missileImpact'||type==='groundBlast'||type==='boom'){
  const wreck=type==='boom',ground=type==='groundBlast';
  sample('blast',now,wreck?.92:ground?.70:.87,wreck?.71:ground?.91:1.05,pan,0,'blast',wreck?.42:ground?.31:.37);
  sample('pressure',now+.012,wreck?.75:ground?.43:.62,wreck?.74:.95,pan);
  if(!ground)sample('metal',now+.046,wreck?.34:.38,wreck?.68:.90,pan,0,'metal',.15);
  if(wreck)sample('action',now+.19,.22,.71,pan);
  return true;
 }
 return false;
}
